const aiResponse = $input.item.json.message.content;
let newsletter;
try { newsletter = JSON.parse(aiResponse); } catch (e) { newsletter = { subject: 'Newsletter Wellness', sections: [] }; }

// Build HTML
let html = `<div style="max-width:600px;margin:0 auto;font-family:'Helvetica Neue',Arial,sans-serif;color:#333;">`;
html += `<div style="background:#f5f0eb;padding:30px;text-align:center;"><h1 style="color:#2d2d2d;font-size:24px;">${newsletter.subject?.replace(/^[^\w]+ /, '') || 'Newsletter Wellness'}</h1></div>`;

for (const section of (newsletter.sections || [])) {
  html += `<div style="padding:20px 30px;"><h2 style="color:#6b5b4e;font-size:18px;">${section.title}</h2><p style="line-height:1.6;">${section.content}</p>`;
  if (section.cta) html += `<a href="#" style="display:inline-block;background:#6b5b4e;color:white;padding:12px 24px;text-decoration:none;border-radius:25px;margin:10px 0;">${section.cta}</a>`;
  html += `</div><hr style="border:none;border-top:1px solid #e8e0d8;margin:0 30px;">`;
}

if (newsletter.wellness_tip) {
  html += `<div style="padding:20px 30px;background:#f9f6f2;"><h3 style="color:#6b5b4e;">Tip Wellness de la semaine</h3><p style="line-height:1.6;">${newsletter.wellness_tip}</p></div>`;
}

html += `<div style="padding:20px 30px;text-align:center;color:#888;font-size:12px;"><p>${newsletter.closing || 'A bientot au studio!'}</p></div></div>`;

return {
  json: {
    subject: newsletter.subject,
    preview_text: newsletter.preview_text,
    html_body: html,
    agent_id: 'email-marketer',
    workflow_id: 'WF-EMAIL-NEWSLETTER'
  }
};
